export function createDebouncer(waitMs) {
  const t = new Map()

  function schedule(key, callback) {
    cancel(key)

    const timer = setTimeout(() => {
      t.delete(key)
      void Promise.resolve()
        .then(callback)
        .catch(() => {})
    }, waitMs)

    t.set(key, timer)
  }

  function cancel(key) {
    const timer = t.get(key)
    if (!timer) return false

    clearTimeout(timer)
    t.delete(key)
    return true
  }

  function cancelAll() {
    for (const timer of t.values()) {
      clearTimeout(timer)
    }
    t.clear()
  }

  return { schedule, cancel, cancelAll }
}
